// Compact street blocks. Building fronts align to shared pavements; whole
// park lots and exit approaches are reserved before any decoration is added.
export function planUrban({config,seed,buildings,exits,random}){
 const metro=config.biome==='metro',cols=config.size==='city'?4+Math.floor(random()*3):config.size==='town'?3+Math.floor(random()*2):3,parkCount=config.size==='city'?3:config.size==='town'?2:1,count=buildings.length+parkCount,rows=Math.ceil(count/cols),slots=Array.from({length:rows*cols},(_,i)=>i);
 const shuffle=a=>{for(let i=a.length-1;i;i--){const j=Math.floor(random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;};shuffle(slots);const items=shuffle([...buildings]).map((t,i)=>({t,row:Math.floor(slots[i]/cols),col:slots[i]%cols})),cw=Array(cols).fill(5),rh=Array(rows).fill(6);for(const p of items){cw[p.col]=Math.max(cw[p.col],p.t.w+1);rh[p.row]=Math.max(rh[p.row],p.t.h+1);}const gap=3,margin=6,xs=[],ys=[];let width=margin,height=margin;for(const n of cw){xs.push(width);width+=n+gap;}width+=margin-gap;for(const n of rh){ys.push(height);height+=n+gap;}height+=margin-gap+(config.biome==='coastal'?8:0);const cells=width*height,blocked=new Uint8Array(cells),frontRows=ys.map((y,i)=>y+rh[i]-1),plots=items.map(p=>({t:p.t,x:xs[p.col]+Math.floor((cw[p.col]-p.t.w)/2),y:frontRows[p.row]-p.t.h}));
 for(const p of plots)for(let y=p.y;y<p.y+p.t.h;y++)for(let x=p.x;x<p.x+p.t.w;x++)blocked[y*width+x]=1;
 const occupiedSlots=new Set(items.map(p=>p.row*cols+p.col)),parks=slots.filter(i=>!occupiedSlots.has(i)).map(i=>{const row=Math.floor(i/cols),col=i%cols;return{x:xs[col],y:ys[row],w:cw[col],h:rh[row]-1};});
 const endpoints=exits.map(e=>{const horizontal=e.edge==='north'||e.edge==='south',n=horizontal?width:height,p=Math.max(3,Math.min(n-4,Math.round((n-1)*e.position/100)));return{...e,x:horizontal?p:e.edge==='west'?0:width-1,y:horizontal?e.edge==='north'?0:height-1:p};});for(let i=0;i<endpoints.length;i++)for(let j=0;j<i;j++)if(Math.abs(endpoints[i].x-endpoints[j].x)+Math.abs(endpoints[i].y-endpoints[j].y)<6)throw Error('Leave six tiles between exits.');
 const road=new Set(),add=(x,y)=>{if(x>=0&&y>=0&&x<width&&y<height&&!blocked[y*width+x])road.add(y*width+x);},vertical=[margin-2,...xs.map((x,i)=>x+cw[i]+1)],horizontal=[margin-2,...frontRows.map(y=>y+1)];for(const x of vertical)for(let y=margin-2;y<=horizontal.at(-1);y++)add(x,y);for(const y of horizontal)for(let x=margin-2;x<=vertical.at(-1);x++)add(x,y);
 const nodes=plots.flatMap(p=>(p.t.entrances?.length?p.t.entrances:[{x:Math.floor(p.t.w/2)}]).map(e=>({x:p.x+e.x,y:p.y+p.t.h}))).concat(endpoints);
 for(const n of nodes){const start=n.y*width+n.x,prev=new Int32Array(cells).fill(-2),queue=[start];prev[start]=-1;let end=null;for(let at=0;at<queue.length;at++){const i=queue[at];if(road.has(i)){end=i;break;}const x=i%width,y=Math.floor(i/width);for(const[dx,dy]of[[0,1],[1,0],[-1,0],[0,-1]]){const xx=x+dx,yy=y+dy,j=yy*width+xx;if(xx<0||yy<0||xx>=width||yy>=height||blocked[j]||prev[j]!==-2)continue;prev[j]=i;queue.push(j);}}if(end===null)throw Error('A city doorway cannot reach the street.');for(let i=end;i!==-1;i=prev[i])road.add(i);}
 for(const i of [...road]){const x=i%width,y=Math.floor(i/width);for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++)add(x+dx,y+dy);}
 for(const i of [...road]){const x=i%width,y=Math.floor(i/width);if((x===0||y===0||x===width-1||y===height-1)&&!endpoints.some(e=>Math.abs(e.x-x)+Math.abs(e.y-y)<=1))road.delete(i);}
 return{...config,width,height,plots,road,exits:endpoints,random,layoutSample:metro?'metro-blocks':'city-blocks',frontRows,parks,urban:true,grid:{columns:cols,rows}};
}
